-- Phase 2 initial migration.
--
-- HAND-WRITTEN, not generated by `prisma migrate dev`.
-- `binaries.prisma.sh` (Prisma's engine-binary CDN) is not in this agent's
-- allowed egress domains (confirmed via `prisma validate`/`generate`/
-- `migrate dev`/`format` all failing identically with 403 on that host,
-- including with PRISMA_ENGINES_CHECKSUM_IGNORE_MISSING=1). No Prisma CLI
-- command could run. This file was derived by hand from
-- apps/api/prisma/schema.prisma and applied directly via `psql` against a
-- real local Postgres instance, then verified with introspection queries
-- (see AGENT_HANDOFF.md for the exact verification performed).
--
-- IMPORTANT for the next agent with binary access: run `prisma migrate dev`
-- against a FRESH database first, to let Prisma generate its own canonical
-- version of this migration and confirm it matches what's below (diff the
-- two). If they match (or differ only in constraint-naming style, not
-- substance), mark this migration as applied on any DB that already has it
-- via `prisma migrate resolve --applied 20260828060000_init` rather than
-- re-running it. If they don't match in substance, that's a bug in this
-- hand-written file to fix, not a schema.prisma problem.

-- ============================================================================
-- Enums
-- ============================================================================

CREATE TYPE "UserRole" AS ENUM ('student', 'professor', 'researcher', 'club_rep', 'startup_member', 'alumni', 'admin');
CREATE TYPE "UserStatus" AS ENUM ('pending_verification', 'active', 'suspended', 'banned');
CREATE TYPE "VerificationRoleClaim" AS ENUM ('professor', 'researcher', 'club_rep', 'startup_member', 'admin');
CREATE TYPE "VerificationStatus" AS ENUM ('pending', 'approved', 'rejected');
CREATE TYPE "ResearcherType" AS ENUM ('phd', 'postdoc', 'research_associate', 'research_assistant', 'faculty');
CREATE TYPE "Visibility" AS ENUM ('public', 'university_only', 'connections_only', 'private');
CREATE TYPE "OrganizationType" AS ENUM ('club', 'society', 'startup');
CREATE TYPE "MembershipRole" AS ENUM ('member', 'leader', 'advisor', 'founder', 'pi');
CREATE TYPE "ProjectStatus" AS ENUM ('idea', 'planning', 'development', 'beta', 'active', 'completed', 'archived');
CREATE TYPE "SkillRoleNeeded" AS ENUM ('frontend', 'backend', 'ml', 'design', 'research', 'product', 'other');
CREATE TYPE "SkillProficiency" AS ENUM ('beginner', 'intermediate', 'advanced', 'expert');
CREATE TYPE "EventType" AS ENUM ('hackathon', 'workshop', 'seminar', 'conference', 'talk', 'guest_lecture', 'competition', 'startup_event', 'club_event');
CREATE TYPE "OpportunityType" AS ENUM ('research', 'internship', 'project', 'startup', 'volunteer', 'club', 'hackathon', 'mentorship', 'thesis', 'research_assistant', 'teaching_assistant');
CREATE TYPE "ApplicationStatus" AS ENUM ('submitted', 'under_review', 'accepted', 'rejected');
CREATE TYPE "ConnectionStatus" AS ENUM ('pending', 'accepted', 'declined', 'blocked');
CREATE TYPE "ConversationType" AS ENUM ('direct', 'group', 'project', 'research_team', 'club');
CREATE TYPE "InvitationType" AS ENUM ('none', 'project', 'research_team');
CREATE TYPE "NotificationType" AS ENUM ('connection_request', 'new_message', 'project_invitation', 'research_invitation', 'club_announcement', 'event_reminder', 'opportunity_deadline', 'new_publication', 'team_recruitment', 'profile_interaction');
CREATE TYPE "ReportTargetType" AS ENUM ('user', 'project', 'organization', 'publication', 'message');
CREATE TYPE "ReportReason" AS ENUM ('fake_account', 'spam', 'harassment', 'impersonation', 'misleading', 'inappropriate');
CREATE TYPE "ReportStatus" AS ENUM ('open', 'reviewing', 'resolved', 'dismissed');
CREATE TYPE "ReportAction" AS ENUM ('none', 'restrict', 'suspend', 'ban');

-- ============================================================================
-- Core Identity
-- ============================================================================

CREATE TABLE "users" (
    "id" UUID NOT NULL DEFAULT gen_random_uuid(),
    "email" TEXT NOT NULL,
    "username" TEXT NOT NULL,
    "phone" TEXT,
    "password_hash" TEXT NOT NULL,
    "requested_role" "UserRole" NOT NULL,
    "status" "UserStatus" NOT NULL DEFAULT 'pending_verification',
    "is_university_verified" BOOLEAN NOT NULL DEFAULT false,
    "university_domain" TEXT,
    "avatar_url" TEXT,
    "is_seed" BOOLEAN NOT NULL DEFAULT false,
    "created_at" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "updated_at" TIMESTAMP(3) NOT NULL,
    CONSTRAINT "users_pkey" PRIMARY KEY ("id")
);
CREATE UNIQUE INDEX "users_email_key" ON "users"("email");
CREATE UNIQUE INDEX "users_username_key" ON "users"("username");
CREATE INDEX "users_status_idx" ON "users"("status");

CREATE TABLE "refresh_tokens" (
    "id" UUID NOT NULL DEFAULT gen_random_uuid(),
    "user_id" UUID NOT NULL,
    "token_hash" TEXT NOT NULL,
    "expires_at" TIMESTAMP(3) NOT NULL,
    "revoked_at" TIMESTAMP(3),
    "is_seed" BOOLEAN NOT NULL DEFAULT false,
    "created_at" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "updated_at" TIMESTAMP(3) NOT NULL,
    CONSTRAINT "refresh_tokens_pkey" PRIMARY KEY ("id")
);
CREATE INDEX "refresh_tokens_user_id_idx" ON "refresh_tokens"("user_id");

CREATE TABLE "verifications" (
    "id" UUID NOT NULL DEFAULT gen_random_uuid(),
    "user_id" UUID NOT NULL,
    "role_claimed" "VerificationRoleClaim" NOT NULL,
    "status" "VerificationStatus" NOT NULL DEFAULT 'pending',
    "reviewed_by" UUID,
    "evidence_url" TEXT,
    "is_seed" BOOLEAN NOT NULL DEFAULT false,
    "created_at" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "updated_at" TIMESTAMP(3) NOT NULL,
    CONSTRAINT "verifications_pkey" PRIMARY KEY ("id")
);
CREATE UNIQUE INDEX "verifications_user_id_role_claimed_key" ON "verifications"("user_id", "role_claimed");
CREATE INDEX "verifications_user_id_idx" ON "verifications"("user_id");
CREATE INDEX "verifications_reviewed_by_idx" ON "verifications"("reviewed_by");

-- ============================================================================
-- Profiles
-- ============================================================================

CREATE TABLE "student_profiles" (
    "user_id" UUID NOT NULL,
    "full_name" TEXT NOT NULL,
    "department" TEXT,
    "course" TEXT,
    "year" INTEGER,
    "university" TEXT,
    "bio" TEXT,
    "cgpa" DECIMAL(3,2),
    "github_url" TEXT,
    "linkedin_url" TEXT,
    "portfolio_url" TEXT,
    "looking_for" JSONB,
    "is_seed" BOOLEAN NOT NULL DEFAULT false,
    "created_at" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "updated_at" TIMESTAMP(3) NOT NULL,
    CONSTRAINT "student_profiles_pkey" PRIMARY KEY ("user_id")
);

CREATE TABLE "professor_profiles" (
    "user_id" UUID NOT NULL,
    "full_name" TEXT NOT NULL,
    "department" TEXT,
    "designation" TEXT,
    "expertise" TEXT[] NOT NULL DEFAULT ARRAY[]::TEXT[],
    "bio" TEXT,
    "office_contact" TEXT,
    "mentorship_available" BOOLEAN NOT NULL DEFAULT false,
    "is_seed" BOOLEAN NOT NULL DEFAULT false,
    "created_at" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "updated_at" TIMESTAMP(3) NOT NULL,
    CONSTRAINT "professor_profiles_pkey" PRIMARY KEY ("user_id")
);

CREATE TABLE "researcher_profiles" (
    "user_id" UUID NOT NULL,
    "full_name" TEXT NOT NULL,
    "researcher_type" "ResearcherType" NOT NULL,
    "department" TEXT,
    "bio" TEXT,
    "current_availability" BOOLEAN NOT NULL DEFAULT true,
    "is_seed" BOOLEAN NOT NULL DEFAULT false,
    "created_at" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "updated_at" TIMESTAMP(3) NOT NULL,
    CONSTRAINT "researcher_profiles_pkey" PRIMARY KEY ("user_id")
);

CREATE TABLE "privacy_settings" (
    "user_id" UUID NOT NULL,
    "profile_visibility" "Visibility" NOT NULL DEFAULT 'university_only',
    "email_visibility" "Visibility" NOT NULL DEFAULT 'connections_only',
    "phone_visibility" "Visibility" NOT NULL DEFAULT 'connections_only',
    "academic_visibility" "Visibility" NOT NULL DEFAULT 'university_only',
    "cgpa_visibility" "Visibility" NOT NULL DEFAULT 'private',
    "projects_visibility" "Visibility" NOT NULL DEFAULT 'public',
    "research_visibility" "Visibility" NOT NULL DEFAULT 'public',
    "social_links_visibility" "Visibility" NOT NULL DEFAULT 'university_only',
    "connections_visibility" "Visibility" NOT NULL DEFAULT 'connections_only',
    "activity_visibility" "Visibility" NOT NULL DEFAULT 'connections_only',
    "contact_visibility" "Visibility" NOT NULL DEFAULT 'connections_only',
    "is_seed" BOOLEAN NOT NULL DEFAULT false,
    "created_at" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "updated_at" TIMESTAMP(3) NOT NULL,
    CONSTRAINT "privacy_settings_pkey" PRIMARY KEY ("user_id")
);

