-- ============================================================================
-- Full-text search: generated tsvector columns + GIN indexes.
-- Per DATABASE_SCHEMA.md "Indexing Summary". Represented in schema.prisma as
-- `Unsupported("tsvector")` fields (Prisma has no generated-column syntax),
-- so `prisma migrate dev`'s drift detection knows about them and won't try
-- to drop them. Phase 5 (search) queries these with $queryRaw.
-- ============================================================================

-- Postgres's built-in array_to_string() is STABLE, not IMMUTABLE, so it
-- cannot be used directly inside a GENERATED ALWAYS AS ... STORED expression
-- (discovered when applying this migration: professor_profiles' column
-- failed with "generation expression is not immutable" while the otherwise
-- identical student_profiles one succeeded, since only professor_profiles'
-- expression touches an array column). Standard, well-documented Postgres
-- workaround: a thin SQL wrapper explicitly marked IMMUTABLE — safe here
-- because array_to_string has no actual non-deterministic behavior of its
-- own; the STABLE label is a conservative default Postgres applies to it.
CREATE OR REPLACE FUNCTION "immutable_array_to_string"(text[], text) RETURNS text AS $$
    SELECT array_to_string($1, $2);
$$ LANGUAGE sql IMMUTABLE PARALLEL SAFE;

ALTER TABLE "student_profiles" ADD COLUMN "search_vector" tsvector
    GENERATED ALWAYS AS (to_tsvector('english', coalesce("bio", ''))) STORED;
CREATE INDEX "student_profiles_search_vector_idx" ON "student_profiles" USING GIN ("search_vector");

ALTER TABLE "professor_profiles" ADD COLUMN "search_vector" tsvector
    GENERATED ALWAYS AS (
        to_tsvector('english', coalesce("bio", '') || ' ' || "immutable_array_to_string"("expertise", ' '))
    ) STORED;
CREATE INDEX "professor_profiles_search_vector_idx" ON "professor_profiles" USING GIN ("search_vector");

ALTER TABLE "researcher_profiles" ADD COLUMN "search_vector" tsvector
    GENERATED ALWAYS AS (to_tsvector('english', coalesce("bio", ''))) STORED;
CREATE INDEX "researcher_profiles_search_vector_idx" ON "researcher_profiles" USING GIN ("search_vector");

